section.script:
function voPickOp(v){
  try{ if(v){ localStorage.setItem('vo_op', v); } else { localStorage.removeItem('vo_op'); } }catch(e){}
  var h = window.location.search.indexOf('hist=1') !== -1 ? '&hist=1' : '';
  window.location.href = '/vue-operateur' + (v ? ('?op=' + encodeURIComponent(v) + h) : '');
}
(function(){
  var params = new URLSearchParams(window.location.search);
  var op = params.get('op');
  if(op){ try{ localStorage.setItem('vo_op', op); }catch(e){} }
  else {
    var s=null; try{ s=localStorage.getItem('vo_op'); }catch(e){}
    if(s){ window.location.replace('/vue-operateur?op=' + encodeURIComponent(s) + (params.get('hist')==='1' ? '&hist=1' : '')); return; }
  }
  if(params.get('hist')==='1'){
    var blocks = Array.prototype.slice.call(document.querySelectorAll('.vo-dayblock'));
    if(!blocks.length){ return; }
    var idx = 0;
    for(var i=0;i<blocks.length;i++){ if(blocks[i].getAttribute('data-today')==='1'){ idx=i; break; } }
    var lbl=document.getElementById('vd-lbl'), prev=document.getElementById('vd-prev'), next=document.getElementById('vd-next');
    function show(){
      for(var i=0;i<blocks.length;i++){ blocks[i].style.display = (i===idx)?'':'none'; }
      if(lbl){ lbl.textContent = blocks[idx].getAttribute('data-label'); }
      if(next){ next.disabled = (idx===0); }
      if(prev){ prev.disabled = (idx===blocks.length-1); }
      window.scrollTo(0,0);
    }
    if(prev){ prev.onclick=function(){ if(idx<blocks.length-1){ idx++; show(); } }; }
    if(next){ next.onclick=function(){ if(idx>0){ idx--; show(); } }; }
    show();
    return;
  }

  function bd(id,m,cls,txt){ return '<button type="button" class="vo-act btn '+cls+'" data-id="'+id+'" data-m="'+m+'">'+txt+'</button>'; }
  function render(card){
    var st=card.getAttribute('data-state');
    var id=card.getAttribute('data-id');
    var badge=card.querySelector('.vo-badge'), acts=card.querySelector('.vo-actions');
    card.classList.toggle('doned', st==='done');
    if(st==='done'){ badge.innerHTML='<span class="badge text-bg-secondary">✓ Terminé</span>'; acts.innerHTML=bd(id,'undo_finish','btn-outline-danger','↩ Annuler Terminé'); }
    else if(st==='progress'){ badge.innerHTML='<span class="badge text-bg-success">▶ En cours</span>'; acts.innerHTML=bd(id,'button_pending','btn-warning','⏸ Pause')+bd(id,'button_finish','btn-success','✓ Terminer'); }
    else if(st==='blocked'){ badge.innerHTML='<span class="badge text-bg-danger">⛔ Bloquée</span>'; acts.innerHTML=''; }
    else { badge.innerHTML='<span class="badge text-bg-light">○ À faire</span>'; acts.innerHTML=bd(id,'button_start','btn-primary','▶ Démarrer'); }
    bind(acts);
  }
  function bind(root){
    root.querySelectorAll('.vo-act').forEach(function(b){
      b.onclick=function(){
        var m=b.getAttribute('data-m'), id=parseInt(b.getAttribute('data-id'));
        var card=b.closest('.vo-card');
        if(m==='button_finish' && !b.getAttribute('data-cf')){
          b.setAttribute('data-cf','1'); b.className='vo-act btn btn-danger'; b.textContent='⚠ Confirmer Terminer ?';
          setTimeout(function(){ if(b.getAttribute('data-cf')){ b.removeAttribute('data-cf'); b.className='vo-act btn btn-success'; b.textContent='✓ Terminer'; } }, 4000);
          return;
        }
        if(m==='undo_finish' && !confirm('Annuler le Terminé de cette opération ?')){ return; }
        b.disabled=true; b.textContent='…';
        var body;
        if(m==='undo_finish'){
          body = {jsonrpc:'2.0',method:'call',params:{model:'ir.actions.server',method:'run',args:[[1940]],kwargs:{context:{active_model:'mrp.workorder',active_ids:[id]}}}};
        } else {
          body = {jsonrpc:'2.0',method:'call',params:{model:'mrp.workorder',method:m,args:[[id]],kwargs:{}}};
        }
        fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
          body:JSON.stringify(body)
        }).then(function(r){return r.json();}).then(function(d){
          if(d.error){ alert('Échec : '+(d.error.data && d.error.data.message || d.error.message)); render(card); renderP(card); return; }
          var ns = m==='button_start' ? 'progress' : (m==='button_pending' || m==='undo_finish' ? 'ready' : 'done');
          card.setAttribute('data-state', ns); render(card); renderP(card); updateCount();
        }).catch(function(e){ alert('Échec : '+e); render(card); renderP(card); });
      };
    });
  }
  function renderP(card){
    var box=card.querySelector('.vo-pieces'); if(!box){ return; }
    var nbr=parseInt(card.getAttribute('data-nbr'))||0;
    var fait=parseInt(card.getAttribute('data-fait'))||0;
    var st=card.getAttribute('data-state');
    if(nbr <= 1 || st==='done' || st==='blocked'){ box.innerHTML=''; return; }
    var reste=Math.max(0, nbr-fait);
    box.innerHTML = '<span class="vo-fait">Fait '+fait+' / '+nbr+'</span>'
      + '<span class="vo-reste'+(reste===0?' zero':'')+'">'+(reste===0?'✅ Tout fait':'Reste '+reste)+'</span>'
      + '<button type="button" class="vo-p1 btn btn-primary"'+(reste===0?' disabled="disabled"':'')+'>+1 pièce</button>'
      + (fait>0 ? '<button type="button" class="vo-m1 btn btn-outline-secondary btn-sm">−1</button>' : '');
    function saveF(nf){
      fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:'mrp.workorder',method:'write',args:[[parseInt(card.getAttribute('data-id'))],{x_studio_nbr_fait:nf}],kwargs:{}}})
      }).then(function(r){return r.json();}).then(function(d){
        if(d.error){ alert('Échec : '+(d.error.data && d.error.data.message || d.error.message)); renderP(card); return; }
        card.setAttribute('data-fait', nf); renderP(card);
      }).catch(function(e){ alert('Échec : '+e); renderP(card); });
    }
    var p1=box.querySelector('.vo-p1'), m1=box.querySelector('.vo-m1');
    if(p1){ p1.onclick=function(){ p1.disabled=true; saveF(fait+1); }; }
    if(m1){ m1.onclick=function(){ saveF(fait-1); }; }
  }
  document.querySelectorAll('.vo-card').forEach(function(c){ render(c); renderP(c); });

  var selC={}, selR={}, dimQ=['','',''];
  function apply(){
    document.querySelectorAll('.vo-card').forEach(function(c){
      var cl=c.getAttribute('data-client')||'', rf=c.getAttribute('data-ref')||'';
      var kc=Object.keys(selC), kr=Object.keys(selR);
      var okC = kc.length===0 || selC[cl];
      var okR = kr.length===0 || selR[rf];
      var okD = true;
      var parts = (c.getAttribute('data-dims')||'').split(' ');
      if(dimQ[0] && (parts[0]||'').indexOf(dimQ[0]) === -1){ okD = false; }
      if(dimQ[1] && (parts[1]||'').indexOf(dimQ[1]) === -1){ okD = false; }
      if(dimQ[2] && (parts[2]||'').indexOf(dimQ[2]) === -1){ okD = false; }
      c.style.display = (okC && okR && okD) ? '' : 'none';
    });
    updateCount();
  }
  var dimIns=[document.getElementById('vo-dim-l'),document.getElementById('vo-dim-la'),document.getElementById('vo-dim-h')];
  var dimX=document.getElementById('vo-dim-x');
  dimIns.forEach(function(inp, i){
    if(!inp){ return; }
    inp.addEventListener('input', function(){
      dimQ[i] = inp.value.trim().replace(',', '.');
      if(dimX){ dimX.style.display = (dimQ[0]||dimQ[1]||dimQ[2]) ? '' : 'none'; }
      apply();
    });
  });
  if(dimX){ dimX.onclick=function(){ dimIns.forEach(function(inp){ if(inp){ inp.value=''; } }); dimQ=['','','']; dimX.style.display='none'; apply(); }; }
  function chip(sel, cls){
    document.querySelectorAll(cls).forEach(function(ch){
      ch.onclick=function(){
        var v=ch.getAttribute('data-val');
        if(sel[v]){ delete sel[v]; ch.classList.remove('on'); } else { sel[v]=1; ch.classList.add('on'); }
        apply();
      };
    });
  }
  chip(selC, '.chip-cli'); chip(selR, '.chip-ref');
  function updateCount(){
    var n=0; document.querySelectorAll('.vo-card').forEach(function(c){ if(c.style.display!=='none' && c.getAttribute('data-state')!=='done'){ n++; } });
    var el=document.getElementById('vo-count'); if(el){ el.innerHTML='<strong>'+n+'</strong> opération(s) à produire'; }
  }
  updateCount();
})();
